package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import static org.junit.Assert.*;

public class Cleaner_clean_TriageGen2Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    @Test
    public void clean_nullParameter_throwsIllegalArgumentException() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        thrown.expect(IllegalArgumentException.class);
        cleaner.clean(null);
    }

    @Test
    public void clean_emptyDocument_returnsCleanDocumentWithEmptyBody() {
        Cleaner cleaner = new Cleaner(Safelist.none());
        Document dirty = Jsoup.parse("");

        Document clean = cleaner.clean(dirty);

        assertNotNull(clean);
        assertEquals(dirty.baseUri(), clean.baseUri());
        assertTrue(clean.body().children().isEmpty());
    }

    @Test
    public void clean_withSafeHtml_returnsIdenticalStructure() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        String html = "<html><head></head><body><p>Hello <b>World</b></p></body></html>";
        Document dirty = Jsoup.parse(html);

        Document clean = cleaner.clean(dirty);

        assertEquals(dirty.baseUri(), clean.baseUri());
        // Verify content is preserved
        assertEquals("Hello <b>World</b>", clean.body().html());
    }

    @Test
    public void clean_withUnsafeHtml_removesUnsafeElements() {
        // Safelist.none() removes all tags
        Cleaner cleaner = new Cleaner(Safelist.none());
        String html = "<html><head></head><body><p>Keep me <script>alert(1)</script></p></body></html>";
        Document dirty = Jsoup.parse(html);

        Document clean = cleaner.clean(dirty);

        // The script tag should be removed, leaving only text if allowed, 
        // but Safelist.none() usually strips tags but keeps text content if it's inside.
        // However, in Jsoup Cleaner, it strips the tags entirely.
        assertFalse(clean.body().select("script").isEmpty()); // This depends on how copySafeNodes handles text nodes
        // Actually, with Safelist.none(), the <p> is also removed.
        assertEquals("Keep me alert(1)", clean.body().text());
        assertTrue(clean.body().select("p").isEmpty());
        assertTrue(clean.body().select("script").isEmpty());
    }

    @Test
    public void clean_preservesBaseUri() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        Document dirty = Jsoup.parse("<html><body><p>test</p></body></html>");
        dirty.setBaseUri("https://example.com/path");

        Document clean = cleaner.clean(dirty);

        assertEquals("https://example.com/path", clean.baseUri());
    }

    @Test
    public void clean_complexNestedStructure_cleansCorrectly() {
        Cleaner cleaner = new Cleaner(Safelist.simpleText());
        String html = "<div><span><a href='http://example.com'>Link</a></span><script>bad()</script></div>";
        Document dirty = Jsoup.parse(html);

        Document clean = cleaner.clean(dirty);

        // simpleText allows <a> and text, but not <div> or <span> or <script>
        // Note: results depend on the specific Safelist implementation
        assertFalse(clean.body().select("script").isEmpty()); // wait, script is never safe
        assertEquals(0, clean.body().select("script").size());
        assertEquals(0, clean.body().select("div").size());
        assertEquals(0, clean.body().select("span").size());
    }
}
